<?php
declare(strict_types=1);
namespace App;
use PDO;use Slim\App;use Psr\Http\Message\ServerRequestInterface as Request;use Psr\Http\Message\ResponseInterface as Response;
final class SubmissionRoutes{use Support;public static function register(App $app,PDO $db,Auth $auth,array $cfg):void{$access=new Access($db);
$app->get('/api/conferences/{conferenceId}/phases',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['chair']);$cid=(int)$a['conferenceId'];$access->requireChair($u,$cid);return Http::json($s,['conference'=>$access->conference($cid),'phases'=>self::all($db,"SELECT phase,starts_at,ends_at,status FROM conference_phases WHERE conference_id=? ORDER BY CASE phase WHEN 'submission' THEN 1 WHEN 'review' THEN 2 WHEN 'rebuttal' THEN 3 ELSE 4 END",[$cid])]);});
$app->put('/api/conferences/{conferenceId}/phases',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['chair']);$cid=(int)$a['conferenceId'];$access->requireChair($u,$cid);$d=self::body($r);self::required($d,['phases']);$order=['submission','review','rebuttal','decision'];$last=null;foreach($order as $phase){if(!isset($d['phases'][$phase]))throw new ApiException(422,'validation_failed','All four phases are required.',['phases'=>$phase.' is missing.']);$x=$d['phases'][$phase];self::required($x,['startsAt','endsAt']);$start=strtotime($x['startsAt']);$end=strtotime($x['endsAt']);if(!$start||!$end||$start>=$end||($last!==null&&$start<=$last))throw new ApiException(422,'invalid_phase_schedule','Phase dates must be ordered and non-overlapping.',['phases'=>'Invalid '.$phase.' window.']);$last=$end;}$db->beginTransaction();$st=$db->prepare("UPDATE conference_phases SET starts_at=?,ends_at=?,status='inactive' WHERE conference_id=? AND phase=?");foreach($order as $phase){$x=$d['phases'][$phase];$st->execute([$x['startsAt'],$x['endsAt'],$cid,$phase]);}$db->prepare('UPDATE conferences SET active_phase=NULL WHERE id=?')->execute([$cid]);$db->prepare("INSERT INTO audit_events(actor_id,action,entity_type,entity_id) VALUES(?,'configure_phases','conference',?)")->execute([$u['id'],$cid]);$db->commit();return Http::json($s,['phases'=>self::all($db,"SELECT phase,starts_at,ends_at,status FROM conference_phases WHERE conference_id=? ORDER BY id",[$cid])]);});
$app->post('/api/conferences/{conferenceId}/phases/{phase}/activate',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['chair']);$cid=(int)$a['conferenceId'];$phase=$a['phase'];$access->requireChair($u,$cid);if(!in_array($phase,['submission','review','rebuttal','decision'],true))throw new ApiException(404,'phase_not_found','Phase not found.');self::one($db,'SELECT id FROM conference_phases WHERE conference_id=? AND phase=?',[$cid,$phase],'phase_not_found');$db->beginTransaction();$db->prepare("UPDATE conference_phases SET status=CASE WHEN status='active' THEN 'completed' ELSE status END WHERE conference_id=?")->execute([$cid]);$db->prepare("UPDATE conference_phases SET status='active' WHERE conference_id=? AND phase=?")->execute([$cid,$phase]);$db->prepare('UPDATE conferences SET active_phase=? WHERE id=?')->execute([$phase,$cid]);$db->prepare("INSERT INTO audit_events(actor_id,action,entity_type,entity_id) VALUES(?,'activate_{$phase}','conference',?)")->execute([$u['id'],$cid]);$db->commit();return Http::json($s,['conference'=>$access->conference($cid)]);});

$app->post('/api/conferences/{conferenceId}/submissions',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['author']);$cid=(int)$a['conferenceId'];$access->conference($cid);$access->requirePhase($cid,'submission');$d=self::body($r);self::required($d,['title','abstract','keywords','track']);if(!is_array($d['keywords'])||!count($d['keywords']))throw new ApiException(422,'validation_failed','At least one keyword is required.',['keywords'=>'Required.']);$coauthors=array_values(array_unique(array_map('intval',$d['coauthorIds']??[])));$db->beginTransaction();$db->prepare('INSERT INTO submissions(conference_id,title,abstract,keywords_json,track,status) VALUES(?,?,?,?,?,?)')->execute([$cid,trim($d['title']),trim($d['abstract']),json_encode(array_values($d['keywords'])),trim($d['track']),'submitted']);$id=(int)$db->lastInsertId();$db->prepare('INSERT INTO submission_authors(submission_id,user_id,author_order,is_corresponding) VALUES(?,?,1,1)')->execute([$id,$u['id']]);$position=2;foreach($coauthors as $uid){if($uid===(int)$u['id'])continue;self::one($db,"SELECT id FROM users WHERE id=? AND role='author'",[$uid],'coauthor_not_found');$db->prepare('INSERT INTO submission_authors(submission_id,user_id,author_order) VALUES(?,?,?)')->execute([$id,$uid,$position++]);}$db->prepare("INSERT INTO submission_activity(submission_id,actor_id,event,details) VALUES(?,?,'submission_created','Submission created.')")->execute([$id,$u['id']]);$db->prepare("INSERT INTO notifications(user_id,type,message,link) SELECT user_id,'submission',?,? FROM conference_chairs WHERE conference_id=?")->execute(['New submission: '.trim($d['title']),'/submissions/'.$id,$cid]);$db->commit();return Http::json($s,['submission'=>self::projection($db,$access->submission($id),$u,$access)],201);});
$app->patch('/api/submissions/{submissionId}',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['author']);$sub=$access->submission((int)$a['submissionId']);if(!$access->isAuthor((int)$sub['id'],(int)$u['id']))throw new ApiException(403,'author_access_required','Only submission authors may edit.');$access->requirePhase((int)$sub['conference_id'],'submission');if($sub['status']==='withdrawn')throw new ApiException(409,'submission_withdrawn','Withdrawn submissions cannot be edited.');$d=self::body($r);if(isset($d['version'])&&(int)$d['version']!==(int)$sub['version'])throw new ApiException(409,'stale_version','Submission changed in another request.');$map=['title'=>'title','abstract'=>'abstract','track'=>'track'];$sets=[];$p=[];foreach($map as $in=>$col)if(array_key_exists($in,$d)){$sets[]="$col=?";$p[]=trim((string)$d[$in]);}if(array_key_exists('keywords',$d)){$sets[]='keywords_json=?';$p[]=json_encode(array_values($d['keywords']));}if(!$sets)throw new ApiException(422,'validation_failed','No supported fields supplied.');$sets[]='version=version+1';$sets[]="updated_at=datetime('now')";$p[]=$sub['id'];$db->prepare('UPDATE submissions SET '.implode(',',$sets).' WHERE id=?')->execute($p);return Http::json($s,['submission'=>self::projection($db,$access->submission((int)$sub['id']),$u,$access)]);});
$app->post('/api/submissions/{submissionId}/manuscript',function(Request $r,Response $s,array $a)use($auth,$db,$access,$cfg){$u=$auth->requireUser($r,['author']);$sub=$access->submission((int)$a['submissionId']);if(!$access->isAuthor((int)$sub['id'],(int)$u['id']))throw new ApiException(403,'author_access_required','Only submission authors may upload.');$access->requirePhase((int)$sub['conference_id'],'submission');$files=$r->getUploadedFiles();if(!isset($files['manuscript'])||$files['manuscript']->getError()!==UPLOAD_ERR_OK)throw new ApiException(422,'validation_failed','A manuscript PDF is required.',['manuscript'=>'Required.']);$f=$files['manuscript'];$name=(string)$f->getClientFilename();$mime=(string)$f->getClientMediaType();if(strtolower(pathinfo($name,PATHINFO_EXTENSION))!=='pdf'||$mime!=='application/pdf')throw new ApiException(422,'validation_failed','Manuscript must be a PDF.',['manuscript'=>'PDF required.']);if($f->getSize()>$cfg['maxUpload'])throw new ApiException(422,'validation_failed','Manuscript is too large.',['manuscript'=>'Above configured maximum.']);$dir=str_starts_with($cfg['uploadDir'],'/')?$cfg['uploadDir']:dirname(__DIR__).'/'.$cfg['uploadDir'];if(!is_dir($dir))mkdir($dir,0775,true);$stored=bin2hex(random_bytes(16)).'.pdf';$f->moveTo($dir.'/'.$stored);$db->beginTransaction();$db->prepare('INSERT INTO stored_files(original_name,stored_name,mime_type,size_bytes) VALUES(?,?,?,?)')->execute([$name,$stored,'application/pdf',$f->getSize()]);$fileId=(int)$db->lastInsertId();$max=self::one($db,'SELECT COALESCE(MAX(version),0) v FROM manuscripts WHERE submission_id=?',[$sub['id']]);$version=(int)$max['v']+1;$db->prepare('UPDATE manuscripts SET is_current=0 WHERE submission_id=?')->execute([$sub['id']]);$db->prepare('INSERT INTO manuscripts(submission_id,file_id,version,uploaded_by) VALUES(?,?,?,?)')->execute([$sub['id'],$fileId,$version,$u['id']]);$id=(int)$db->lastInsertId();$db->prepare("INSERT INTO submission_activity(submission_id,actor_id,event,details) VALUES(?,?,'manuscript_uploaded',?)")->execute([$sub['id'],$u['id'],'Version '.$version]);$db->commit();return Http::json($s,['manuscript'=>self::one($db,'SELECT id,submission_id,version,created_at FROM manuscripts WHERE id=?',[$id])],201);});
$app->post('/api/submissions/{submissionId}/withdraw',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['author']);$sub=$access->submission((int)$a['submissionId']);if(!$access->isAuthor((int)$sub['id'],(int)$u['id']))throw new ApiException(403,'author_access_required','Only submission authors may withdraw.');if($sub['status']==='withdrawn')return Http::json($s,['submission'=>$sub]);$db->beginTransaction();$db->prepare("UPDATE submissions SET status='withdrawn',version=version+1,updated_at=datetime('now') WHERE id=?")->execute([$sub['id']]);$db->prepare("INSERT INTO submission_activity(submission_id,actor_id,event,details) VALUES(?,?,'submission_withdrawn','Submission withdrawn.')")->execute([$sub['id'],$u['id']]);$db->commit();return Http::json($s,['submission'=>$access->submission((int)$sub['id'])]);});

$app->get('/api/submissions',function(Request $r,Response $s)use($auth,$db,$access){$u=$auth->requireUser($r,['author','reviewer','chair']);$q=$r->getQueryParams();[$limit,$offset,$page]=self::page($r);$where=[];$p=[];if($u['role']==='author'){$where[]='EXISTS(SELECT 1 FROM submission_authors sa WHERE sa.submission_id=s.id AND sa.user_id=?)';$p[]=$u['id'];}elseif($u['role']==='reviewer'){$where[]='EXISTS(SELECT 1 FROM review_assignments ra WHERE ra.submission_id=s.id AND ra.reviewer_id=?)';$p[]=$u['id'];}else{$where[]='EXISTS(SELECT 1 FROM conference_chairs cc WHERE cc.conference_id=s.conference_id AND cc.user_id=?)';$p[]=$u['id'];}foreach(['status'=>'s.status','track'=>'s.track'] as $key=>$col)if(trim($q[$key]??'')!==''){$where[]="$col=?";$p[]=trim($q[$key]);}if(trim($q['q']??'')!==''){$where[]='(s.title LIKE ? OR s.abstract LIKE ?)';$term='%'.trim($q['q']).'%';$p[]=$term;$p[]=$term;}$sql='SELECT s.* FROM submissions s WHERE '.implode(' AND ',$where).' ORDER BY s.created_at DESC,s.id DESC LIMIT ? OFFSET ?';$p[]=$limit;$p[]=$offset;$rows=self::all($db,$sql,$p);foreach($rows as &$row)$row=self::projection($db,$row,$u,$access);return Http::json($s,['items'=>$rows,'page'=>$page,'limit'=>$limit]);});
$app->get('/api/submissions/{submissionId}',function(Request $r,Response $s,array $a)use($auth,$access,$db){$u=$auth->requireUser($r,['author','reviewer','chair']);$sub=$access->submission((int)$a['submissionId']);$access->requireSubmissionAccess($u,$sub);return Http::json($s,['submission'=>self::projection($db,$sub,$u,$access)]);});
$app->get('/api/submissions/{submissionId}/manuscript',function(Request $r,Response $s,array $a)use($auth,$access,$db,$cfg){$u=$auth->requireUser($r,['author','reviewer','chair']);$sub=$access->submission((int)$a['submissionId']);$access->requireSubmissionAccess($u,$sub);$m=self::one($db,'SELECT m.*,f.original_name,f.stored_name,f.mime_type FROM manuscripts m JOIN stored_files f ON f.id=m.file_id WHERE m.submission_id=? AND m.is_current=1',[$sub['id']],'manuscript_not_found');$dir=str_starts_with($cfg['uploadDir'],'/')?$cfg['uploadDir']:dirname(__DIR__).'/'.$cfg['uploadDir'];$path=$dir.'/'.$m['stored_name'];if(!is_file($path))throw new ApiException(404,'manuscript_not_found','Manuscript file is unavailable.');$s->getBody()->write((string)file_get_contents($path));$filename=$u['role']==='reviewer'?'submission-'.$sub['id'].'-blinded.pdf':$m['original_name'];return $s->withHeader('Content-Type','application/pdf')->withHeader('Content-Disposition','attachment; filename="'.str_replace('"','',$filename).'"');});
}
private static function projection(PDO $db,array $sub,array $u,Access $access):array{$sub['keywords']=json_decode($sub['keywords_json'],true);unset($sub['keywords_json']);if($u['role']==='reviewer'){unset($sub['created_at'],$sub['updated_at']);return$sub;}$sub['authors']=self::all($db,'SELECT u.id,u.name,u.email,u.affiliation,sa.author_order,sa.is_corresponding FROM submission_authors sa JOIN users u ON u.id=sa.user_id WHERE sa.submission_id=? ORDER BY sa.author_order',[$sub['id']]);return$sub;}}
